const req = $input.first().json;
const p = Object.assign({}, req.query || {}, req.body || {});
const fn = p.wsfunction;
const now = Math.floor(Date.now() / 1000);
const dia = 86400;

// Datos ficticios del curso. Reemplaza los teléfonos por los números de prueba de WhatsApp (formato 51XXXXXXXXX).
const curso = { id: 101, shortname: 'PBI-2026', fullname: 'Especialización en Power BI potenciado con IA' };
const alumnos = [
  { id: 1, username: 'enrique.ramos', firstname: 'Enrique', lastname: 'Ramos', email: 'enrique.ramos@demo.pe', telefono: '51900000001' },
  { id: 2, username: 'luis.castro', firstname: 'Luis', lastname: 'Castro', email: 'luis.castro@demo.pe', telefono: '51900000002' },
  { id: 3, username: 'mariana.lopez', firstname: 'Mariana', lastname: 'López', email: 'mariana.lopez@demo.pe', telefono: '51900000003' },
  { id: 4, username: 'jorge.quispe', firstname: 'Jorge', lastname: 'Quispe', email: 'jorge.quispe@demo.pe', telefono: '51900000004' },
  { id: 5, username: 'carla.mendoza', firstname: 'Carla', lastname: 'Mendoza', email: 'carla.mendoza@demo.pe', telefono: '51900000005' },
  { id: 6, username: 'diego.flores', firstname: 'Diego', lastname: 'Flores', email: 'diego.flores@demo.pe', telefono: '51900000006' }
];
const tareas = [
  { id: 201, cmid: 501, course: 101, name: 'Reto 1: Modelo de datos de ventas', intro: '<p>Construye un modelo estrella con las tablas Ventas, Productos, Clientes y Calendario. Define las relaciones y su cardinalidad.</p>', duedate: now - 3 * dia, allowsubmissionsfromdate: now - 10 * dia },
  { id: 202, cmid: 502, course: 101, name: 'Reto 2: Medidas DAX de rentabilidad', intro: '<p>Crea las medidas Margen Bruto, Margen % y Ventas Año Anterior. Muestra en un informe la variación interanual por categoría.</p>', duedate: now + 3 * dia, allowsubmissionsfromdate: now - 2 * dia }
];
const entregas = {
  201: [1, 2, 3, 4, 5, 6],
  202: [2, 3, 5]
};

let respuesta;
switch (fn) {
  case 'core_webservice_get_site_info':
    respuesta = { sitename: 'DMC Aula Virtual (simulado)', release: '4.3 (Build: demo)', functions: [] };
    break;
  case 'core_enrol_get_enrolled_users':
    respuesta = alumnos.map(a => ({
      id: a.id, username: a.username, firstname: a.firstname, lastname: a.lastname,
      fullname: a.firstname + ' ' + a.lastname, email: a.email,
      customfields: [{ type: 'text', value: a.telefono, name: 'Teléfono', shortname: 'telefono' }],
      roles: [{ roleid: 5, name: '', shortname: 'student', sortorder: 0 }],
      enrolledcourses: [{ id: curso.id, fullname: curso.fullname, shortname: curso.shortname }]
    }));
    break;
  case 'mod_assign_get_assignments':
    respuesta = { courses: [{ id: curso.id, fullname: curso.fullname, shortname: curso.shortname, assignments: tareas }], warnings: [] };
    break;
  case 'mod_assign_get_submissions':
    respuesta = {
      assignments: tareas.map(t => ({
        assignmentid: t.id,
        submissions: (entregas[t.id] || []).map(uid => ({ id: t.id * 100 + uid, userid: uid, status: 'submitted', timemodified: now - dia }))
      })),
      warnings: []
    };
    break;
  default:
    respuesta = { exception: 'invalid_parameter_exception', errorcode: 'invalidparameter', message: 'Función no disponible en el simulador: ' + fn };
}

return [{ json: { respuesta } }];
